styles.h1:
font-size: 32px;
color: #5e6fff;
margin-bottom: 12px;
letter-spacing: 0.5px;
font-weight: 700;
text-align: center;
position: relative;
padding-bottom: 16px;
transition: all 0.3s ease;

styles.h2:
font-size: 24px;
color: #8c9eff;
margin-bottom: 24px;
font-weight: 600;
letter-spacing: 0.5px;
position: relative;
padding-left: 20px;
border-left: 4px solid #7c8dff;
transition: all 0.3s ease;

styles.h3:
font-size: 20px;
color: #5e6fff;
margin-bottom: 16px;
font-weight: 600;
position: relative;
padding-left: 16px;
border-left: 3px solid #8c9eff;
transition: all 0.3s ease;

styles.h6:
color: #6b8c42;
margin-top: 1.2em;
margin-bottom: 0.5em;
font-weight: 700;
border-bottom: 1px solid #d4d9c9;
padding-bottom: 0.3em;
transition: all 0.3s ease;

styles.p:
color: #666;
font-size: 15px;
line-height: 1.8;
margin: 16px 0;
transition: all 0.3s ease;

styles.strong:
color: #5e6fff;
font-weight: 600;
background-color: rgba(94, 111, 255, 0.1);
padding: 2px 6px;
border-radius: 4px;
transition: all 0.3s ease;

styles.em:
color: #8c9eff;
font-style: italic;
transition: all 0.3s ease;

styles.a:
color: #7c8dff;
text-decoration: none;
border-bottom: 1px dashed #d8e1ff;
transition: all 0.3s ease;
padding: 0 2px;

styles.ul:
padding-left: 0;
background: rgba(255, 255, 255, 0.7);
border-radius: 12px;
padding: 20px 25px;
box-shadow: 0 4px 15px rgba(0, 0, 0, 0.03);
border: 1px solid rgba(124, 141, 255, 0.1);
transition: all 0.3s ease;

styles.ol:
background: rgba(255, 255, 255, 0.7);
border-radius: 12px;
padding: 20px 25px;
box-shadow: 0 4px 15px rgba(0, 0, 0, 0.03);
border: 1px solid rgba(124, 141, 255, 0.1);
counter-reset: item;
transition: all 0.3s ease;

styles.li:
position: relative;


margin: 16px 0;
padding-left: 46px;
color: #666;
font-size: 15px;
transition: all 0.3s ease;

styles.blockquote:
background: linear-gradient(135deg, #f5f7ff 0%, #e8f0ff 100%);
border-left: 4px solid #7c8dff;
color: #7c8dff;
padding: 20px 24px;
margin: 24px 0;
border-radius: 0 12px 12px 0;
position: relative;
transition: all 0.3s ease;

styles.code:
display: inline-block;
padding: 4px 8px;
line-height: 1.5;
background: rgba(94, 111, 255, 0.1);
color: #5e6fff;
border-radius: 6px;
font-family: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
font-size: 14px;
transition: all 0.3s ease;

styles.pre:
background: rgba(245, 247, 255, 0.9);
border: 1px solid #e5e7eb;
box-shadow: 0 4px 15px rgba(149, 175, 255, 0.15);
border-radius: 12px;
padding: 20px 24px;
overflow-x: auto;
line-height: 1.6;
transition: all 0.3s ease;

styles.hr:
background: linear-gradient(to right, transparent, #7c8dff, transparent);
height: 2px;
margin: 32px 0;
border: none;
transition: all 0.3s ease;

styles.img:
max-width: 100%;
border: 2px solid #f5f0ff;
box-shadow: 0 4px 15px rgba(136, 99, 207, 0.1);
border-radius: 12px;
margin: 24px auto;
display: block;
transition: all 0.3s ease;

styles.table:
box-shadow: 0 4px 15px rgba(149, 175, 255, 0.15);
border-radius: 12px;
overflow: hidden;
width: 100%;
margin: 24px 0;
border-collapse: collapse;
transition: all 0.3s ease;

styles.th:
background: linear-gradient(135deg, #f5f7ff 0%, #e8f0ff 100%);
color: #7c8dff;
border-bottom: 2px solid #d8e1ff;
padding: 16px 20px;
text-align: left;
font-weight: 600;
transition: all 0.3s ease;

styles.td:
color: #666;
padding: 14px 20px;
border-bottom: 1px solid #e8f0ff;
transition: all 0.3s ease;

